#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define rep(i, n) for(int i = 0; i < n; ++i)
#define MAX_N (int)2e+5

vector<long long>a;
vector<pair<int,ll> >e[MAX_N];

ll dfs(int k,int p){
	ll mx=0,tmp;
	int sz=e[k].size();
	rep(i,sz){
		if(e[k][i].first!=p){
			tmp=dfs(e[k][i].first,k)+e[k][i].second;
			if(tmp>mx){
				a.push_back(mx);
				mx=tmp;
			}
			else a.push_back(tmp);
		}
	}
	return mx;
}

int main(void){
	int n,u,v,sz;
	ll x;
	cin>>n;
	rep(i,n-1){
		cin>>u>>v>>x;
		u--,v--;
		e[u].push_back({v,x});
		e[v].push_back({u,x});
	}
	a.push_back(dfs(0,-1));
	sort(a.begin(),a.end());
	x=0;
	sz=a.size();
	rep(i,n){
		x+=a[sz-i-1]*2;
		cout<<x<<endl;
	}

	return 0;
}
